const MAX_OWNER_PROMPT_SENDERS=16;const MAX_OWNER_PROMPT_CONTENT_BYTES=980;function exceedsOwnerPromptContentBudget(e){let t=0;for(const n of e){t+=Buffer.byteLength(n,`utf8`)+(t>0?2:0);if(t>980)return true}return false}function resolveOwnerPromptNumbers(e){const t=e.ownerNumbers;if(!t?.length)return;if(t.length<=MAX_OWNER_PROMPT_SENDERS&&!exceedsOwnerPromptContentBudget(t))return t;const n=t.slice(0,MAX_OWNER_PROMPT_SENDERS);const r=e.senderId;if(e.senderIsOwner&&r&&t.includes(r)){if(!n.includes(r))n[n.length-1]=r;if(exceedsOwnerPromptContentBudget(n)&&n[0]!==r)return[r,...n.filter(e=>e!==r)]}return n}export{resolveOwnerPromptNumbers as t};